<?php require __DIR__.'/core/bootstrap.php';$u=auth();$p=one('SELECT * FROM products WHERE id=? AND visible=1',[(int)($_GET['produto']??0)]);if(!$p){http_response_code(404);exit('Produto não encontrado.');}$error='';if(is_post()){verify_csrf();try{if(!rate_limit('order',15,3600))throw new InvalidArgumentException('Muitas solicitações. Aguarde antes de enviar novamente.');$domain=domain(input('domain',253));$notes=input('notes',6000);$now=date('Y-m-d H:i:s');run('INSERT INTO orders (user_id,product_id,product_name,amount,status,domain,notes,created_at,updated_at) VALUES (?,?,?,?,\'requested\',?,?,?,?)',[$u['id'],$p['id'],$p['name'],$p['price'],$domain,$notes,$now,$now]);audit('pedido_criado','Pedido #'.db()->lastInsertId());flash('Pedido recebido. Aguarde a proposta e as orientações da equipe.');go('cliente/pedidos.php');}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}$pageTitle='Solicitar produto — S7VEN';require ROOT.'/includes/header.php';?><main class="readable"><h1><?=e($p['name'])?></h1><p><?=e(money($p['price']))?>. A contratação e o pagamento são combinados com o atendimento. Esta solicitação não cobra seu cartão e não envia itens para o jogo.</p><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;?><form method="post"><?php csrf();?><label class="field">Domínio do servidor (sem https ou caminho)<input name="domain" required maxlength="253" placeholder="meuservidor.com.br"></label><label class="field">Versão e observações<textarea name="notes" maxlength="6000"></textarea></label><button class="primary">Confirmar solicitação ↗</button></form></main><?php require ROOT.'/includes/footer.php';?>
